#include <stdio.h>
#include <string.h>

#define MAX_EVENTS 105
#define MAX_HANDLERS 50

typedef void (*EventHandler)(int event_id, void *data);

typedef struct {
    char name[32];
    EventHandler func;
    int is_active;
} HandlerEntry;

typedef struct {
    HandlerEntry handlers[MAX_HANDLERS];
    int count;
} EventChannel;

static EventChannel channels[MAX_EVENTS];

static void generic_callback(int event_id, void *data) {
    // Dummy callback if needed
}

static void register_handler(int event_id, const char *name) {
    if (event_id < 0 || event_id >= MAX_EVENTS) return;
    EventChannel *chan = &channels[event_id];
    if (chan->count < MAX_HANDLERS) {
        strncpy(chan->handlers[chan->count].name, name, 31);
        chan->handlers[chan->count].name[31] = '\0';
        chan->handlers[chan->count].func = generic_callback;
        chan->handlers[chan->count].is_active = 1;
        chan->count++;
    }
}

static void unregister_handler(int event_id, const char *name) {
    if (event_id < 0 || event_id >= MAX_EVENTS) return;
    EventChannel *chan = &channels[event_id];
    for (int i = 0; i < chan->count; i++) {
        if (chan->handlers[i].is_active && strcmp(chan->handlers[i].name, name) == 0) {
            chan->handlers[i].is_active = 0;
            break;
        }
    }
}

static void dispatch_event(int event_id, int payload) {
    if (event_id < 0 || event_id >= MAX_EVENTS) {
        printf("NO HANDLERS FOR EVENT %d\n", event_id);
        return;
    }
    EventChannel *chan = &channels[event_id];
    int active_found = 0;
    for (int i = 0; i < chan->count; i++) {
        if (chan->handlers[i].is_active) {
            active_found = 1;
            printf("%s received event %d with payload %d\n", chan->handlers[i].name, event_id, payload);
        }
    }
    if (!active_found) {
        printf("NO HANDLERS FOR EVENT %d\n", event_id);
    }
}

int main(void) {
    int q;
    if (scanf("%d", &q) != 1) return 0;

    char cmd[32];
    for (int i = 0; i < q; i++) {
        if (scanf("%31s", cmd) != 1) break;
        if (strcmp(cmd, "REGISTER") == 0) {
            int eid;
            char name[32];
            scanf("%d %31s", &eid, name);
            register_handler(eid, name);
        } else if (strcmp(cmd, "UNREGISTER") == 0) {
            int eid;
            char name[32];
            scanf("%d %31s", &eid, name);
            unregister_handler(eid, name);
        } else if (strcmp(cmd, "DISPATCH") == 0) {
            int eid, payload;
            scanf("%d %d", &eid, &payload);
            dispatch_event(eid, payload);
        }
    }

    return 0;
}

description:
The standard C library function `qsort` achieves compile-time type agnosticism by utilizing `void *` pointers and user-supplied comparator callbacks:
`void generic_sort(void *base, size_t num, size_t size, int (*compar)(const void *, const void *));`

Because `void *` cannot be dereferenced or incremented directly, pointer arithmetic must be performed by casting to byte pointers (`char *`), calculating memory offsets as `(char *)base + i * size`. Swapping two elements requires byte-by-byte memory swapping across their `size` bytes.

Implement a generic sorting algorithm (such as Insertion Sort or Bubble Sort) from scratch conforming to this generic signature. Demonstrate its polymorphism by sorting two distinct data types:
- **Type 1 (Integers)**: An array of 32-bit signed integers, sorted in ascending numeric order.
- **Type 2 (Student Records)**: An array of student structs:
  ```c
  typedef struct {
      int id;
      char name[20];
      int marks;
  } Student;
  ```
  Sorted by `marks` in **descending** order. If two students have identical marks, break ties by `id` in **ascending** order.

Read the type indicator and elements from standard input, execute your custom `generic_sort`, and output the sorted collection.

