#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    char name[20];
    int marks;
} Student;

static void swap_bytes(char *a, char *b, size_t size) {
    for (size_t i = 0; i < size; i++) {
        char temp = a[i];
        a[i] = b[i];
        b[i] = temp;
    }
}

void generic_sort(void *base, size_t num, size_t size, int (*compar)(const void *, const void *)) {
    char *arr = (char *)base;
    for (size_t i = 0; i < num; i++) {
        for (size_t j = 0; j + 1 < num - i; j++) {
            char *p1 = arr + j * size;
            char *p2 = arr + (j + 1) * size;
            if (compar(p1, p2) > 0) {
                swap_bytes(p1, p2, size);
            }
        }
    }
}

static int compare_ints(const void *a, const void *b) {
    int valA = *(const int *)a;
    int valB = *(const int *)b;
    if (valA < valB) return -1;
    if (valA > valB) return 1;
    return 0;
}

static int compare_students(const void *a, const void *b) {
    const Student *s1 = (const Student *)a;
    const Student *s2 = (const Student *)b;
    // Marks descending
    if (s1->marks != s2->marks) {
        return (s2->marks - s1->marks);
    }
    // ID ascending
    return (s1->id - s2->id);
}

int main(void) {
    int t, n;
    if (scanf("%d %d", &t, &n) != 2) return 0;

    if (t == 1) {
        int *arr = (int *)malloc(n * sizeof(int));
        for (int i = 0; i < n; i++) {
            scanf("%d", &arr[i]);
        }
        generic_sort(arr, n, sizeof(int), compare_ints);
        for (int i = 0; i < n; i++) {
            printf("%d%c", arr[i], (i == n - 1) ? '\n' : ' ');
        }
        free(arr);
    } else if (t == 2) {
        Student *students = (Student *)malloc(n * sizeof(Student));
        for (int i = 0; i < n; i++) {
            scanf("%d %19s %d", &students[i].id, students[i].name, &students[i].marks);
        }
        generic_sort(students, n, sizeof(Student), compare_students);
        for (int i = 0; i < n; i++) {
            printf("%d %s %d\n", students[i].id, students[i].name, students[i].marks);
        }
        free(students);
    }

    return 0;
}

