#include <stdio.h>
#include <string.h>

static int get_type_size(const char *type) {
    if (strcmp(type, "char") == 0) return 1;
    if (strcmp(type, "short") == 0) return 2;
    if (strcmp(type, "int") == 0) return 4;
    if (strcmp(type, "long") == 0) return 8;
    if (strcmp(type, "double") == 0) return 8;
    if (strcmp(type, "pointer") == 0) return 8;
    return 1;
}

static int get_effective_align(int natural_align, int pack_val) {
    if (pack_val > 0 && pack_val < natural_align) {
        return pack_val;
    }
    return natural_align;
}

int main(void) {
    int p, m;
    if (scanf("%d %d", &p, &m) != 2) return 0;

    int current_offset = 0;
    int max_align = 1;

    for (int i = 0; i < m; i++) {
        char name[32], type[32];
        scanf("%31s %31s", name, type);

        int size = get_type_size(type);
        int natural_align = size;
        int eff_align = get_effective_align(natural_align, p);

        if (eff_align > max_align) {
            max_align = eff_align;
        }

        int padding = 0;
        int rem = current_offset % eff_align;
        if (rem != 0) {
            padding = eff_align - rem;
        }

        int offset = current_offset + padding;
        printf("%s: offset=%d, size=%d, padding=%d\n", name, offset, size, padding);
        current_offset = offset + size;
    }

    // Trailing padding to align struct total size
    int trailing_padding = 0;
    int rem = current_offset % max_align;
    if (rem != 0) {
        trailing_padding = max_align - rem;
    }
    int total_size = current_offset + trailing_padding;

    printf("Total struct size: %d, alignment: %d\n", total_size, max_align);
    return 0;
}

