static int is_little_endian(void) {
    unsigned int x = 1;
    return (*((unsigned char *)&x) == 1);
}

static unsigned int swap_bytes32(unsigned int val) {
    return ((val >> 24) & 0x000000FFU) |
           ((val >> 8)  & 0x0000FF00U) |
           ((val << 8)  & 0x00FF0000U) |
           ((val << 24) & 0xFF000000U);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    if (is_little_endian()) {
        printf("Host Endianness: Little-Endian\n");
    } else {
        printf("Host Endianness: Big-Endian\n");
    }

    for (int i = 0; i < n; i++) {
        unsigned int val;
        scanf("%x", &val);

        unsigned int swapped = swap_bytes32(val);

        unsigned char b0 = (unsigned char)(val & 0xFF);
        unsigned char b1 = (unsigned char)((val >> 8) & 0xFF);
        unsigned char b2 = (unsigned char)((val >> 16) & 0xFF);
        unsigned char b3 = (unsigned char)((val >> 24) & 0xFF);

        printf("Input: 0x%08X | Swapped: 0x%08X | LE-Bytes: %02X %02X %02X %02X | BE-Bytes: %02X %02X %02X %02X\n",
               val, swapped, b0, b1, b2, b3, b3, b2, b1, b0);
    }

    return 0;
}

