#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int *data;
    int capacity;
    int head; // next write index
    int tail; // next read index
    int count;
} CircularBuffer;

static void init_buffer(CircularBuffer *cb, int capacity) {
    cb->data = (int *)malloc(capacity * sizeof(int));
    cb->capacity = capacity;
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
}

static void enqueue_reject(CircularBuffer *cb, int val) {
    if (cb->count == cb->capacity) {
        printf("BUFFER_FULL\n");
        return;
    }
    cb->data[cb->head] = val;
    cb->head = (cb->head + 1) % cb->capacity;
    cb->count++;
}

static void enqueue_overwrite(CircularBuffer *cb, int val) {
    if (cb->count == cb->capacity) {
        // Overwrite oldest item: advance tail
        cb->data[cb->head] = val;
        cb->head = (cb->head + 1) % cb->capacity;
        cb->tail = (cb->tail + 1) % cb->capacity;
    } else {
        cb->data[cb->head] = val;
        cb->head = (cb->head + 1) % cb->capacity;
        cb->count++;
    }
}

static void dequeue(CircularBuffer *cb) {
    if (cb->count == 0) {
        printf("BUFFER_EMPTY\n");
        return;
    }
    int val = cb->data[cb->tail];
    cb->tail = (cb->tail + 1) % cb->capacity;
    cb->count--;
    printf("%d\n", val);
}

static void peek(CircularBuffer *cb) {
    if (cb->count == 0) {
        printf("BUFFER_EMPTY\n");
        return;
    }
    printf("%d\n", cb->data[cb->tail]);
}

int main(void) {
    int c, q;
    if (scanf("%d %d", &c, &q) != 2) return 0;

    CircularBuffer cb;
    init_buffer(&cb, c);

    char cmd[32];
    for (int i = 0; i < q; i++) {
        if (scanf("%31s", cmd) != 1) break;
        if (strcmp(cmd, "ENQUEUE_REJECT") == 0) {
            int val;
            scanf("%d", &val);
            enqueue_reject(&cb, val);
        } else if (strcmp(cmd, "ENQUEUE_OVERWRITE") == 0) {
            int val;
            scanf("%d", &val);
            enqueue_overwrite(&cb, val);
        } else if (strcmp(cmd, "DEQUEUE") == 0) {
            dequeue(&cb);
        } else if (strcmp(cmd, "PEEK") == 0) {
            peek(&cb);
        } else if (strcmp(cmd, "COUNT") == 0) {
            printf("%d\n", cb.count);
        }
    }

    free(cb.data);
    return 0;
}

