#include <stdio.h>
#include <string.h>

#define MAX_BLOCKS 2005

typedef struct {
    int offset;
    int size;
    int is_free;
    int id;
} Block;

static Block pool[MAX_BLOCKS];
static int block_count = 0;

static void init_pool(int total_size) {
    pool[0].offset = 0;
    pool[0].size = total_size;
    pool[0].is_free = 1;
    pool[0].id = -1;
    block_count = 1;
}

static void alloc_mem(int id, int size) {
    for (int i = 0; i < block_count; i++) {
        if (pool[i].is_free && pool[i].size >= size) {
            int rem = pool[i].size - size;
            if (rem >= 16) {
                // Shift subsequent blocks right
                for (int j = block_count; j > i + 1; j--) {
                    pool[j] = pool[j - 1];
                }
                pool[i + 1].offset = pool[i].offset + size;
                pool[i + 1].size = rem;
                pool[i + 1].is_free = 1;
                pool[i + 1].id = -1;
                block_count++;

                pool[i].size = size;
            }
            pool[i].is_free = 0;
            pool[i].id = id;
            printf("ALLOCATED %d AT OFFSET %d\n", id, pool[i].offset);
            return;
        }
    }
    printf("ALLOCATION_FAILED %d\n", id);
}

static void free_mem(int id) {
    int target = -1;
    for (int i = 0; i < block_count; i++) {
        if (!pool[i].is_free && pool[i].id == id) {
            target = i;
            break;
        }
    }
    if (target == -1) {
        printf("INVALID_FREE %d\n", id);
        return;
    }

    pool[target].is_free = 1;
    pool[target].id = -1;

    // Coalesce with right neighbor
    if (target + 1 < block_count && pool[target + 1].is_free) {
        pool[target].size += pool[target + 1].size;
        for (int j = target + 1; j < block_count - 1; j++) {
            pool[j] = pool[j + 1];
        }
        block_count--;
    }

    // Coalesce with left neighbor
    if (target - 1 >= 0 && pool[target - 1].is_free) {
        pool[target - 1].size += pool[target].size;
        for (int j = target; j < block_count - 1; j++) {
            pool[j] = pool[j + 1];
        }
        block_count--;
    }

    printf("FREED %d\n", id);
}

static void stats_mem(void) {
    int free_blocks = 0;
    int total_free = 0;
    int largest_free = 0;

    for (int i = 0; i < block_count; i++) {
        if (pool[i].is_free) {
            free_blocks++;
            total_free += pool[i].size;
            if (pool[i].size > largest_free) {
                largest_free = pool[i].size;
            }
        }
    }
    printf("FREE_BLOCKS: %d, TOTAL_FREE: %d, LARGEST_FREE: %d\n", free_blocks, total_free, largest_free);
}

int main(void) {
    int m, q;
    if (scanf("%d %d", &m, &q) != 2) return 0;

    init_pool(m);

    char cmd[32];
    for (int i = 0; i < q; i++) {
        if (scanf("%31s", cmd) != 1) break;
        if (strcmp(cmd, "ALLOC") == 0) {
            int id, size;
            scanf("%d %d", &id, &size);
            alloc_mem(id, size);
        } else if (strcmp(cmd, "FREE") == 0) {
            int id;
            scanf("%d", &id);
            free_mem(id);
        } else if (strcmp(cmd, "STATS") == 0) {
            stats_mem();
        }
    }

    return 0;
}

