#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

#define MAX_PAIRS 200
#define MAX_PATH 128
#define MAX_VAL 128

typedef struct {
    char path[MAX_PATH];
    char value[MAX_VAL];
} Entry;

static Entry entries[MAX_PAIRS];
static int entry_count = 0;

static char scope_stack[16][64];
static int scope_depth = 0;

static void trim_trailing(char *s) {
    size_t len = strlen(s);
    while (len > 0 && (s[len - 1] == ' ' || s[len - 1] == '\t' || s[len - 1] == '\n' || s[len - 1] == '\r' || s[len - 1] == ',')) {
        s[len - 1] = '\0';
        len--;
    }
}

static void build_full_path(char *dest, const char *key) {
    dest[0] = '\0';
    for (int i = 0; i < scope_depth; i++) {
        strcat(dest, scope_stack[i]);
        strcat(dest, ".");
    }
    strcat(dest, key);
}

int main(void) {
    int l;
    if (scanf("%d", &l) != 1) return 0;

    char line[512];
    fgets(line, sizeof(line), stdin); // consume newline

    for (int line_num = 1; line_num <= l; line_num++) {
        if (!fgets(line, sizeof(line), stdin)) break;
        trim_trailing(line);

        char *p = line;
        while (*p == ' ' || *p == '\t') p++;
        if (*p == '\0') continue;

        if (*p == '}') {
            if (scope_depth > 0) scope_depth--;
            continue;
        }

        if (*p != '"') {
            printf("SYNTAX_ERROR AT LINE %d\n", line_num);
            continue;
        }

        // Extract key
        p++; // skip opening quote
        char *key_end = strchr(p, '"');
        if (!key_end) {
            printf("SYNTAX_ERROR AT LINE %d\n", line_num);
            continue;
        }
        *key_end = '\0';
        char key[64];
        strncpy(key, p, 63);
        key[63] = '\0';

        p = key_end + 1;
        while (*p == ' ' || *p == '\t') p++;
        if (*p != ':') {
            printf("SYNTAX_ERROR AT LINE %d\n", line_num);
            continue;
        }
        p++; // skip colon
        while (*p == ' ' || *p == '\t') p++;

        if (*p == '{') {
            // Nested object
            if (scope_depth < 16) {
                strncpy(scope_stack[scope_depth], key, 63);
                scope_stack[scope_depth][63] = '\0';
                scope_depth++;
            }
            continue;
        }

        // Value: either quoted string or number
        char val[MAX_VAL] = "";
        if (*p == '"') {
            p++;
            char *val_end = strchr(p, '"');
            if (!val_end) {
                printf("SYNTAX_ERROR AT LINE %d\n", line_num);
                continue;
            }
            *val_end = '\0';
            strncpy(val, p, MAX_VAL - 1);
        } else {
            // Number
            char *num_start = p;
            while (*p && *p != ' ' && *p != ',' && *p != '}') p++;
            *p = '\0';
            // Validate integer
            int valid = 1;
            char *chk = num_start;
            if (*chk == '-' || *chk == '+') chk++;
            if (*chk == '\0') valid = 0;
            while (*chk) {
                if (!isdigit((unsigned char)*chk)) { valid = 0; break; }
                chk++;
            }
            if (!valid) {
                printf("SYNTAX_ERROR AT LINE %d\n", line_num);
                continue;
            }
            strncpy(val, num_start, MAX_VAL - 1);
        }

        char full_path[MAX_PATH];
        build_full_path(full_path, key);

        if (entry_count < MAX_PAIRS) {
            strncpy(entries[entry_count].path, full_path, MAX_PATH - 1);
            strncpy(entries[entry_count].value, val, MAX_VAL - 1);
            entry_count++;
        }
    }

    int q;
    if (scanf("%d", &q) != 1) return 0;

    for (int i = 0; i < q; i++) {
        char query_cmd[16], path[MAX_PATH];
        if (scanf("%15s %127s", query_cmd, path) != 2) break;

        int found = 0;
        for (int j = 0; j < entry_count; j++) {
            if (strcmp(entries[j].path, path) == 0) {
                printf("GET %s = %s\n", path, entries[j].value);
                found = 1;
                break;
            }
        }
        if (!found) {
            printf("KEY_NOT_FOUND\n");
        }
    }

    return 0;
}
